import{_ as t,c as s,o,ag as a}from"./chunks/framework.BeChtK_P.js";const n="/images/2025/qemu-install.png",r="/images/2025/qemu-ga.png",i="/images/2025/windows7-driver.png",w=JSON.parse('{"title":"PVE在windows7虚拟机安装 QEMU Guest Agent","description":"本文介绍了在PVE环境下为Windows 7虚拟机安装QEMU Guest Agent的方法，通过VxKex API扩展解决qemu-ga.exe兼容性问题，确保虚拟机正常运行。","frontmatter":{"title":"PVE在windows7虚拟机安装 QEMU Guest Agent","author":"welpher.yu","date":"2025-11-06T15:00:11.000Z","tags":["Nas","PVE"],"categories":["居家折腾","服务器"],"description":"本文介绍了在PVE环境下为Windows 7虚拟机安装QEMU Guest Agent的方法，通过VxKex API扩展解决qemu-ga.exe兼容性问题，确保虚拟机正常运行。"},"headers":[],"relativePath":"posts/2025/proxmox-windows7-qemu-guest-agent.md","filePath":"posts/2025/proxmox-windows7-qemu-guest-agent.md"}'),g={name:"posts/2025/proxmox-windows7-qemu-guest-agent.md"};function m(p,e,x,d,u,_){return o(),s("div",null,[...e[0]||(e[0]=[a('<p>这个问题是由于 qemu-ga.exe 的兼容问题引起的，尝试了网络上很多教程都没有搞定。最终以下面的方法安装成功：</p><p>安装<a href="https://github.com/i486/VxKex" target="_blank" rel="noreferrer">VxKex</a> ， VxKex 是一组针对 Windows 7 的 API 扩展，它使得一些原本只能在 Windows 8、8.1 和 10 上运行的专属应用程序能够在 Windows 7 上运行。 运行 virtio 驱动光盘中的 guest-agent 目录下的 qemu-ga-x86_64 （64 位 Windows 7，32 位同理）复制出来，右键属性点开,修改 VxKex 设置: <img src="'+n+'" alt="qemu-install"></p><p>在安装过程中，打开 Program files\\qemu-ga 目录，然后找到 qemu-ga.exe，右键选择 属性，修改 VxKex 设置后确定。 <img src="'+r+'" alt="qemu-ga"> 安装过程将如果弹出启动服务失败，重试就可以，否则就直接安装完成退出。</p><p>【注意】 设备管理器中的驱动必须要安装好，在设备管理器中右键,更新驱动选第二个选项，选择从virtio-win这个更新驱动。 <img src="'+i+'" alt="windows7-driver"> 本处理在 0.1.271 版本测试通过，更新的版本需要看情况而定。 VxKex 仅支持 Windows 7 SP1 版本，未安装 SP 的需要先升级到 SP1，使用<a href="https://blog.simplix.info/update7/" target="_blank" rel="noreferrer">Update7R2</a>更新补丁。</p>',4)])])}const c=t(g,[["render",m]]);export{w as __pageData,c as default};
